/* Types */
/**  How far an agent may go in the page. */
export type AgentBrowserAccess = 
/**  The agent gets no browser tools at all. */
"off" | 
/**  It can open pages, read them and take screenshots, but not click, type or choose. */
"readOnly" | 
/**  It can use the page like a person. */
"full";

export type AgentEntry = {
	harness: HarnessId,
	/**  The CLI is on this computer's PATH. */
	found: boolean,
	/**
	 *  Lynx's hooks for the agent. Installed means the agent is on: Lynx follows its sessions and
	 *  offers it in the new-terminal menu.
	 */
	hooks: HookInstallStatus,
};

/**  What the user sees for an agent session. `Done` means it finished and nobody has looked yet. */
export type AgentStatus = "working" | "needsYou" | "done" | "idle";

/**  What a session is running now: a harness and its status, or nothing for a plain shell. */
export type AgentStatusChanged = {
	id: string,
	harness: HarnessId | null,
	status: AgentStatus | null,
};

/**  How agents are started from a new terminal. */
export type AgentsConfig = {
	launchMode: LaunchMode,
	/**
	 *  Arguments typed after an agent's command when a terminal starts it. An agent is in this map
	 *  when its arguments are on; an empty text means on, with no arguments of its own.
	 */
	launchArguments: Partial<{ [key in HarnessId]: string }>,
};

/**  The effective settings: what `~/.lynx/config.json` says, with defaults for the rest. */
export type AppConfig = {
	terminal: TerminalConfig,
	worktrees: WorktreesConfig,
	agents: AgentsConfig,
	git: GitConfig,
	notifications: NotificationsConfig,
	browser: BrowserConfig,
	usage: UsageConfig,
};

export type AppInfo = {
	name: string,
	version: string,
};

/**  What a bell from a program does. Sound is left out: the terminal engine only reports the bell. */
export type BellStyle = "none" | "visual";

/**  A branch against its remote. `upstream` is `None` for a branch that was never pushed. */
export type BranchSync = {
	/**  `None` on a detached HEAD. */
	branch: string | null,
	upstream: string | null,
	/**  Commits the branch has that its upstream does not: what a push would send. */
	ahead: number,
	behind: number,
	/**  The remote a push goes to: `origin` when there is one, else the first. `None` without remotes. */
	remote: string | null,
	/**
	 *  The branch is both ahead and behind, and every commit only the remote has is an older copy
	 *  of one that was rewritten here (an amend, a rebase). A plain push is refused then; a force push
	 *  with lease is the way, and a pull would only bring the old copies back.
	 */
	rewritten: boolean,
};

/**  Sent when an agent uses the browser, so the interface can show the page it is working on. */
export type BrowserAgentActivity = {
	tool: string,
	/**  A short line for the interface, such as "Opening example.com". */
	summary: string,
	/**  Who is acting, as the person knows it: "Claude Code", "Codex"... */
	agent: string,
};

/**  Sent when no agent is in control of the page any more. */
export type BrowserAgentReleased = Record<string, never>;

/**  What agents may do in Lynx's browser. */
export type BrowserConfig = {
	agentAccess: AgentBrowserAccess,
	/**  Sites agents may visit, each covering its subdomains. Empty means any site. */
	allowedSites: string[],
};

/**  What the interface shows about the browser: its status and the page it is on. */
export type BrowserState = {
	status: BrowserStatus,
	url: string,
	title: string,
	loading: boolean,
	canGoBack: boolean,
	canGoForward: boolean,
	error: string | null,
	/**  The page is shown in its own window, not in the main one. */
	detached: boolean,
};

/**  Sent whenever the browser's state changes. */
export type BrowserStateChanged = {
	state: BrowserState,
};

export type BrowserStatus = 
/**  No engine process: never started, closed, or stopped on purpose. */
"stopped" | "starting" | "running" | 
/**  The engine could not start or went away; `error` says why. */
"failed";

export type ChangeKind = "added" | "modified" | "deleted" | "renamed" | "copied" | "typeChanged" | "untracked" | "conflicted";

/**  One path as Git reports it: what is staged and what is not, which can differ. */
export type ChangedFile = {
	/**  Relative to the worktree, with `/`. */
	path: string,
	/**  Where a renamed or copied file came from. */
	originalPath: string | null,
	/**  The change in the index (what the next commit would hold). */
	staged: ChangeKind | null,
	/**  The change in the working tree that is not staged yet. Untracked and conflicted files are here. */
	unstaged: ChangeKind | null,
	/**  Lines added and removed by the staged change. `None` for a binary file or a failed read. */
	stagedLines: LineCounts | null,
	/**  The same for the change that is not staged. An untracked file counts as all added. */
	unstagedLines: LineCounts | null,
};

export type CheckLog = {
	text: string,
	/**  The start of the log was cut: only its end is shown. */
	truncated: boolean,
};

export type CheckState = "passed" | "failed" | "pending" | "skipped";

/**
 *  Themes the terminal can use. `Default` is the look the app has always had. A theme
 *  gives the background; its text palette can also be used for the text.
 */
export type ColorScheme = "default" | "light" | "solarizedDark" | "solarizedLight" | "dracula" | "nord" | "catppuccinLatte" | "catppuccinFrappe" | "catppuccinMacchiato" | "catppuccinMocha" | "gruvboxDark" | "oneDark" | "tokyoNight" | "monokai";

export type CommitEntry = {
	hash: string,
	shortHash: string,
	subject: string,
	author: string,
	/**  Seconds since 1970, as git records them. */
	timestamp: number,
	/**
	 *  `false` for a commit the branch's upstream does not have. Without an upstream, nothing is
	 *  known about the remote, so every commit reads as not pushed.
	 */
	pushed: boolean,
};

/**  One file a commit touched, with the lines it added and removed. */
export type CommitFile = {
	path: string,
	/**  Where a renamed or copied file came from. */
	originalPath: string | null,
	kind: ChangeKind,
	lines: LineCounts | null,
};

/**  Which agent CLI writes a commit message. `Auto` takes the first one installed. */
export type CommitMessageAgent = "auto" | "claude" | "codex" | "opencode";

/**  The style part of a commit message instruction. Lynx's output rules always follow it. */
export type CommitMessageStyle = "conventional" | "plain" | "custom";

/**  The config file changed outside the app (an editor, a dotfiles sync, a script). */
export type ConfigChanged = {
	snapshot: ConfigSnapshot,
};

/**  One thing wrong with the config, addressed by its dotted key (`terminal.fontSize`). */
export type ConfigIssue = {
	key: string,
	message: string,
};

/**  What the interface sees: the effective settings plus everything it should warn about. */
export type ConfigSnapshot = {
	config: AppConfig,
	issues: ConfigIssue[],
	path: string,
	fileExists: boolean,
	/**  The file exists but is not valid JSON, so settings cannot be saved over it. */
	fileBroken: boolean,
};

